<?php
declare(strict_types=1);
if(!defined('PLEKSI_APP')){http_response_code(404);exit;}
function xml_mapping(): array {return ['itemPath'=>'products.product','id'=>'id','name'=>'name','description'=>'description','price'=>'price','category'=>'category','image'=>'image'];}
function public_ip(string $ip): bool {
 $packed=@inet_pton($ip);if($packed===false)return false;if(strlen($packed)===16&&substr($packed,0,12)===str_repeat("\0",10)."\xff\xff")$ip=inet_ntop(substr($packed,12));
 if(!filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))return false;
 if(filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_IPV4)){foreach([['100.64.0.0',10],['198.18.0.0',15],['192.0.0.0',24],['192.0.2.0',24],['198.51.100.0',24],['203.0.113.0',24]] as [$net,$bits])if((ip2long($ip)&(-1<<(32-$bits)))===(ip2long($net)&(-1<<(32-$bits))))return false;return true;}
 $n=strtolower($ip);return (ord($packed[0])&0xe0)===0x20&&!str_starts_with($n,'2001:db8:')&&!str_starts_with($n,'2002:')&&substr($packed,0,4)!=="\x20\x01\x00\x00"&&substr($packed,0,4)!=="\x20\x01\x0d\xb8";
}
function fetch_public(string $url,int $max=5242880): string {
 $u=parse_url($url);if(!$u||($u['scheme']??'')!=='https'||isset($u['user'])||isset($u['pass'])||isset($u['fragment'])||(($u['port']??443)!==443)||empty($u['host']))fail('Kimlik bilgisi içermeyen doğrudan HTTPS kaynağı kullanın.');$host=trim($u['host'],'[]');$ips=[];
 if(filter_var($host,FILTER_VALIDATE_IP))$ips=[$host];else{foreach(dns_get_record($host,DNS_A|DNS_AAAA)?:[] as $r){if(isset($r['ip']))$ips[]=$r['ip'];if(isset($r['ipv6']))$ips[]=$r['ipv6'];}}
 if(!$ips)fail('Kaynak alan adının adresi bulunamadı.');foreach($ips as $ip)if(!public_ip($ip))fail('Yerel, özel veya ayrılmış ağ adreslerine erişilemez.');$target=$ips[0];$bytes='';$large=false;$ch=curl_init($url);
 curl_setopt_array($ch,[CURLOPT_FOLLOWLOCATION=>false,CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>20,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_PROXY=>'',CURLOPT_RESOLVE=>[$host.':443:'.(str_contains($target,':')?'['.$target.']':$target)],CURLOPT_HTTPHEADER=>['Accept: application/xml,text/xml,image/*','Accept-Encoding: identity'],CURLOPT_WRITEFUNCTION=>function($c,$chunk)use(&$bytes,&$large,$max){if(strlen($bytes)+strlen($chunk)>$max){$large=true;return 0;}$bytes.=$chunk;return strlen($chunk);}]);
 $ok=curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$error=curl_errno($ch);curl_close($ch);if($large)fail('Kaynak dosya boyutu sınırı aşıldı.');if($ok===false||$error)fail('Kaynağa güvenli bağlantı kurulamadı. Hosting dış bağlantı iznini ve kaynağın TLS sertifikasını kontrol edin.');if($status!==200)fail('Kaynak HTTP '.$status.' yanıtı verdi. Yönlendirme varsa doğrudan son HTTPS bağlantısını girin.');return $bytes;
}
function xml_nodes(SimpleXMLElement $root,string $path,bool $rootPath=false): array {
 if($path==='')return [];$parts=explode('.',$path);$nodes=[$root];if($rootPath&&($parts[0]??'')===$root->getName())array_shift($parts);
 foreach($parts as $part){if(!preg_match('/^(?:@_)?[a-zA-Z_][a-zA-Z0-9_:-]*$/D',$part))fail('XML alan yollarını kontrol edin.');$next=[];foreach($nodes as $node){if(str_starts_with($part,'@_')){foreach($node->attributes() as $name=>$a)if($name===substr($part,2))$next[]=$a;}else foreach($node->children() as $name=>$child)if($name===$part)$next[]=$child;}$nodes=$next;}return $nodes;
}
function parse_xml(string $xml,array $map,float $commission): array {
 if(strlen($xml)>5*1024*1024)fail('XML en fazla 5 MB olabilir.');if(preg_match('/<!DOCTYPE|<!ENTITY/i',$xml))fail('DTD ve ENTITY tanımları desteklenmez.');if(!is_finite($commission)||$commission<0||$commission>100)fail('Komisyon oranı %0–100 arasında olmalı.');foreach(['itemPath','id','name','price'] as $k)if(!valid_text($map[$k]??null,1,150))fail('Ürün yolu, kod, ad ve fiyat alanlarını eşleştirin.');libxml_use_internal_errors(true);$root=simplexml_load_string($xml,SimpleXMLElement::class,LIBXML_NONET|LIBXML_NOCDATA|LIBXML_NOBLANKS);libxml_clear_errors();if($root===false)fail('XML belgesi geçersiz.');$nodes=xml_nodes($root,$map['itemPath'],true);if(!count($nodes)||count($nodes)>1000)fail('Ürün yolu bulunamadı veya 1.000 ürün sınırı aşıldı.');$seen=[];$products=[];
 foreach($nodes as $n){$value=fn($key)=>trim((string)(xml_nodes($n,(string)($map[$key]??''))[0]??''));$id=$value('id');$name=$value('name');$raw=$value('price');if(str_contains($raw,','))$raw=str_replace(',','.',str_replace('.','',$raw));if(!is_numeric($raw)||!valid_text($id,1,150)||!valid_text($name,2,150)||isset($seen[$id])||(float)$raw<1||(float)$raw>1000000)fail((count($products)+1).'. üründe kimlik, ad veya fiyat geçersiz/tekrarlı.');$seen[$id]=true;$images=[];foreach(xml_nodes($n,(string)($map['image']??'')) as $image){$url=trim((string)$image);if($url!=='')$images[]=$url;} $products[]=['externalId'=>$id,'name'=>$name,'description'=>mb_substr($value('description'),0,3000),'category'=>mb_substr($value('category'),0,100)?:'Hediye Setleri','price'=>round((float)$raw,2),'commissionPercent'=>$commission,'remoteImages'=>array_slice($images,0,3)];
 }return $products;
}
function xml_route(string $route,string $method,array $b): void {
 global $user,$db;
 if($route==='/admin/xml/sources'&&$method==='GET')out(array_map(function($s){$s['id']=(int)$s['id'];$s['commission']=(float)$s['commission'];$s['mapping']=dec($s['mapping']);return $s;},rows('SELECT * FROM ph_xml_sources ORDER BY id')));
 if($route==='/admin/xml/sources'&&$method==='POST'){$u=parse_url(is_string($b['url']??null)?$b['url']:'');$c=$b['commissionPercent']??20;if(!valid_text($b['name']??null,1,100)||!$u||($u['scheme']??'')!=='https'||empty($u['host'])||isset($u['user'])||isset($u['pass'])||!money_value($c,0,100))fail('Kaynak adı, HTTPS bağlantısı ve %0–100 komisyon girin.');$map=array_replace(xml_mapping(),is_array($b['mapping']??null)?$b['mapping']:[]);sql('INSERT INTO ph_xml_sources(name,url,mapping,commission) VALUES(?,?,?,?)',[$b['name'],$b['url'],enc($map),$c]);out(['id'=>(int)$db->lastInsertId()],201);}
 if($route==='/admin/xml/runs'&&$method==='GET')out(array_map(function($r){$r['id']=(int)$r['id'];$r['count']=(int)$r['count'];return $r;},rows('SELECT * FROM ph_xml_runs ORDER BY id DESC LIMIT 20')));
 if($route==='/admin/xml/preview'&&$method==='POST'){$source=null;if(!empty($b['sourceId'])){$source=one('SELECT * FROM ph_xml_sources WHERE id=?',[$b['sourceId']]);if(!$source)fail('Kaynak bulunamadı.');$xml=fetch_public($source['url']);$map=dec($source['mapping']);$commission=(float)$source['commission'];}else{$xml=is_string($b['xml']??null)?$b['xml']:'';$map=array_replace(xml_mapping(),is_array($b['mapping']??null)?$b['mapping']:[]);$rawCommission=$b['commissionPercent']??20;if(!money_value($rawCommission,0,100))fail('Komisyon oranı %0–100 arasında olmalı.');$commission=(float)$rawCommission;} $products=parse_xml($xml,$map,$commission);sql('DELETE FROM ph_xml_previews WHERE expires<?',[now_ms()]);if((int)one('SELECT COUNT(*) AS n FROM ph_xml_previews')['n']>=50)fail('Çok fazla bekleyen önizleme var.');$token=bin2hex(random_bytes(24));$data=['products'=>$products,'sourceKey'=>$source?'source:'.$source['id']:'manual:'.hash('sha256',enc($map)),'sourceId'=>$source?(int)$source['id']:null];sql('INSERT INTO ph_xml_previews(token,user_id,expires,data) VALUES(?,?,?,?)',[$token,$user['id'],now_ms()+600000,enc($data)]);out(['token'=>$token,'products'=>$products]);}
 if($route==='/admin/xml/import'&&$method==='POST'){
  $preview=atomic(function()use($b,$user){$p=one('SELECT * FROM ph_xml_previews WHERE token=? AND user_id=? FOR UPDATE',[$b['token']??'',$user['id']]);if(!$p||$p['expires']<now_ms())fail('Önizleme süresi dolmuş; yeniden önizleyin.');sql('DELETE FROM ph_xml_previews WHERE token=?',[$p['token']]);return dec($p['data']);});
  try{$prepared=[];$size=0;$deadline=microtime(true)+70;foreach($preview['products'] as $row){$images=[];foreach($row['remoteImages'] as $url){if(microtime(true)>$deadline)fail('Aktarım süresi sınırı aşıldı. Kaynağı daha küçük parçalara ayırın.');$bytes=fetch_public($url);$size+=strlen($bytes);if($size>50*1024*1024)fail('Toplam görsel boyutu 50 MB sınırını aşıyor.');$images[]=['data'=>$bytes,'mime'=>image_mime($bytes)];}unset($row['remoteImages']);$prepared[]=['fields'=>$row,'images'=>$images];}
  atomic(function()use($prepared,$preview,$user){foreach($prepared as $r){$key=hash('sha256',$preview['sourceKey']."\0".$r['fields']['externalId']);$row=one('SELECT id,data FROM ph_products WHERE xml_key=? FOR UPDATE',[$key]);$old=$row?dec($row['data']):[];$images=[];foreach($r['images'] as $im)$images[]=upload_save($im['data'],(int)$user['id']);$p=array_replace($old,$r['fields'],['xmlSource'=>$preview['sourceKey'],'images'=>$images?:($old['images']??[]),'active'=>$old['active']??false,'requireText'=>$old['requireText']??false,'requireImage'=>$old['requireImage']??false,'kind'=>$old['kind']??'name','color'=>$old['color']??'rose','tag'=>'XML']);if($row)$p['id']=(int)$row['id'];save_product($p,$key);}sql("INSERT INTO ph_xml_runs(source_id,count,status) VALUES(?,?,'Başarılı')",[$preview['sourceId'],count($prepared)]);});out(['imported'=>count($prepared),'message'=>'Ürünler alındı. Yeni ürünler kontrol için pasif oluşturuldu.']);
  }catch(Throwable $e){sql("INSERT INTO ph_xml_runs(source_id,count,status) VALUES(?,0,'Başarısız')",[$preview['sourceId']]);throw $e;}
 }
}
